(5743594, 835410, 100773, '<td valign="top">Funny aproach to the challenge. Good entry! Extra creds for setup</td>', 'Funny aproach to the challenge. Good entry! Extra creds for setup', '2009-11-27 10:01:42.000000', NULL, 1),
(5743600, 835340, 100773, '<td valign="top">I think there''s something funny with the focus (looks like a mix of maximum aperture and cameramovement), can''t realy put my finger on it. Aside from that, excellent photo and a nice way to approach this challenge!</td>', 'I think there''s something funny with the focus (looks like a mix of maximum aperture and cameramovement), can''t realy put my finger on it. Aside from that, excellent photo and a nice way to approach this challenge!', '2009-11-27 10:06:24.000000', NULL, 1),
(5743607, 835405, 100773, '<td valign="top">I really like the colors on your entry. Good capture, and the largest frame I''ve ever seen at dpc somehow enhance the photo. But overall, it looks like a perfect shot of someone that just hit the water from a high jump, I can''t get the science feel from it (then again, who am I to say that with the entry I have...). I believe 6 is a good compromise. I can''t get the science feeling, but your kickassphoto shoehorns its way in, eh?.</td>', 'I really like the colors on your entry. Good capture, and the largest frame I''ve ever seen at dpc somehow enhance the photo. But overall, it looks like a perfect shot of someone that just hit the water from a high jump, I can''t get the science feel from it (then again, who am I to say that with the entry I have...). I believe 6 is a good compromise. I can''t get the science feeling, but your kickassphoto shoehorns its way in, eh?.', '2009-11-27 10:11:50.000000', NULL, 1),
(5743612, 835127, 100773, '<td valign="top">Very good! Nicely done! Hooray! Good vote from me!</td>', 'Very good! Nicely done! Hooray! Good vote from me!', '2009-11-27 10:13:31.000000', NULL, 1),
(5743618, 835307, 100773, '<td valign="top">Another abstraction! Many of them in this challenge, and this one is very good! There''s some kind of noise or something in the dark areas, and I love it!</td>', 'Another abstraction! Many of them in this challenge, and this one is very good! There''s some kind of noise or something in the dark areas, and I love it!', '2009-11-27 10:16:01.000000', NULL, 1),
(5743620, 835158, 100773, '<td valign="top">Nicely done! You nailed this</td>', 'Nicely done! You nailed this', '2009-11-27 10:17:06.000000', NULL, 1),
(5743624, 834856, 100773, '<td valign="top">Sad but true. I especially liked your photo, its a good reflection. Did you open the bottle? It looks like something''s in there. I also like the water. It looks like you have used a slow shutterspeed to blur the water, but the bottle remains sharp. Well done!</td>', 'Sad but true. I especially liked your photo, its a good reflection. Did you open the bottle? It looks like something''s in there. I also like the water. It looks like you have used a slow shutterspeed to blur the water, but the bottle remains sharp. Well done!', '2009-11-27 10:21:13.000000', NULL, 1),
(5743635, 835235, 34659, '<td valign="top">Perfect!</td>', 'Perfect!', '2009-11-27 10:25:06.000000', NULL, 1);
