(5743870, 834678, 83080, '<td valign="top">I love water shots.  Nice sharp refraction.  The composition feels a little off balance to me, but I understand that it can be difficult to get this kind of thing with control over every element.  Good luck!</td>', 'I love water shots.  Nice sharp refraction.  The composition feels a little off balance to me, but I understand that it can be difficult to get this kind of thing with control over every element.  Good luck!', '2009-11-27 14:00:05.000000', NULL, 1),
(5743871, 835236, 83080, '<td valign="top">Cool shot.  It feels slightly off balance to me, but the sharpness and overall capture is fantastic.</td>', 'Cool shot.  It feels slightly off balance to me, but the sharpness and overall capture is fantastic.', '2009-11-27 14:02:15.000000', NULL, 1),
(5743873, 834749, 83080, '<td valign="top">Awesome plasmatic photo!  Love the colors, lines &amp; composition.</td>', 'Awesome plasmatic photo!  Love the colors, lines & composition.', '2009-11-27 14:04:07.000000', NULL, 1),
(5743876, 835381, 83080, '<td valign="top">Very interesting shot.  I wish you had blown out the shadows at the bottom, but the shot is effective overall.</td>', 'Very interesting shot.  I wish you had blown out the shadows at the bottom, but the shot is effective overall.', '2009-11-27 14:05:56.000000', NULL, 1),
